from __future__ import annotations
from typing import Callable

def periodicity_failures(member: Callable[[int], bool], threshold: int, period: int, endpoint: int) -> list[int]:
    if threshold < 0 or period <= 0 or endpoint < threshold:
        raise ValueError("invalid interval or period")
    return [n for n in range(threshold, endpoint + 1) if member(n) != member(n + period)]

from __future__ import annotations
from typing import Sequence

def saturated_union(left: Sequence[int], right: Sequence[int], threshold: int) -> tuple[int, ...]:
    if threshold < 0 or len(left) != len(right):
        raise ValueError("invalid threshold or profile dimensions")
    if any(x < 0 for x in (*left, *right)):
        raise ValueError("counts must be nonnegative")
    return tuple(min(a + b, threshold) for a, b in zip(left, right))

from __future__ import annotations

def power_of_two_period_witness(threshold: int, period: int) -> tuple[int, int]:
    if threshold < 0 or period <= 0:
        raise ValueError("invalid certificate")
    power = 1
    while power <= max(threshold, period):
        power *= 2
    return power, power + period

